const query = $('Webhook').first().json.body.question;
const results = $('Pinecone Vector Store').all();

const documents = results.map(item => ({
  text: (item.json.document.metadata.question || '') + '\n' + (item.json.document.metadata.answer_plain || '')
}));

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.pinecone.io/rerank',
  headers: {
    'Api-Key': 'REDACTED-set-PINECONE_API_KEY-env',
    'Content-Type': 'application/json',
    'X-Pinecone-API-Version': '2025-04'
  },
  body: {
    model: 'bge-reranker-v2-m3',
    query: query,
    top_n: 5,
    return_documents: false,
    documents: documents
  },
  json: true
});

return response.data.map(item => ({
  json: {
    rerank_score: item.score,
    vector_score: results[item.index].json.score,
    question: results[item.index].json.document.metadata.question,
    answer: results[item.index].json.document.metadata.answer_plain,
    stack_name: results[item.index].json.document.metadata.stack_name,
    tags: results[item.index].json.document.metadata.tags,
    last_updated: results[item.index].json.document.metadata.last_updated_date
  }
}));

const query = $('Webhook').first().json.body.question;
const rerankedItems = $('Pinecone Rerank + Map Results').all();

const entries = rerankedItems.map((item, i) => {
  const d = item.json;
  const tags = Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || '');
  return [
    `--- Entry ${i + 1} ---`,
    `Vector Score: ${d.vector_score}`,
    `Rerank Score: ${d.rerank_score}`,
    `Question: ${d.question}`,
    `Tags: ${tags}`,
    `Stack: ${d.stack_name}`,
    `Last Updated: ${d.last_updated || 'unknown'}`,
    `Answer:`,
    d.answer
  ].join('\n');
});

const context = entries.join('\n\n');

const systemPrompt = `You are a PulsePoint pre-sales assistant helping respond to RFI questions. You will be given retrieved entries from PulsePoint's internal Loopio library.

Rules:
- Synthesize a single, complete answer from the retrieved entries.
- Older entries may have stronger foundational detail -- use them as the base.
- Newer entries may contain updated capabilities, stats, or product changes -- layer these in.
- If an older and newer entry conflict, prefer the newer one and briefly note what changed.
- Only use information from the provided entries. Do not make up facts.
- At the end, list which entry numbers you drew from under a "Sources" heading.
- Keep the tone professional and suitable for an RFP response.
- If none of the retrieved entries are relevant, say so clearly.`;

const userMessage = `Retrieved and reranked library entries:\n\n${context}\n\n---\n\nRFI Question: ${query}\n\nPlease synthesize a complete answer using the entries above.`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://us.api.openai.com/v1/chat/completions',
  headers: {
    'Authorization': 'Bearer REDACTED-set-OPENAI_API_KEY',
    'Content-Type': 'application/json'
  },
  body: {
    model: 'gpt-4o',
    max_tokens: 2048,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userMessage }
    ]
  },
  json: true
});

return [{
  json: {
    question: query,
    synthesized_answer: response.choices[0].message.content,
    sources: rerankedItems.map((item, i) => ({
      entry: i + 1,
      rerank_score: item.json.rerank_score,
      question: item.json.question
    }))
  }
}];
